<?php
require __DIR__ . '/_bootstrap.php';global $db;$uid=api_require_user();zv2_refresh($uid);
$items=[];$r=$db->query("SELECT i.id,i.name,i.category,i.attack_bonus,i.healing,i.ammo_item,i.max_durability,i.repair_amount,i.defense_bonus,v.amount,v.durability,COALESCE(personal.used,0) personal,COALESCE(squads.used,0) assigned FROM inventory v JOIN items i ON i.id=v.item_id LEFT JOIN (SELECT equipped_weapon item_id,COUNT(*) used FROM survivors WHERE userid=$uid AND equipped_weapon IS NOT NULL GROUP BY equipped_weapon) personal ON personal.item_id=i.id LEFT JOIN (SELECT se.item_id,SUM(se.amount) used FROM squad_equipment se JOIN squads q ON q.id=se.squad_id WHERE q.userid=$uid GROUP BY se.item_id) squads ON squads.item_id=i.id WHERE v.userid=$uid AND v.amount>0 ORDER BY i.category,i.name");while($r&&($x=$r->fetch_assoc())){$personal=(int)$x['personal'];$assigned=(int)$x['assigned'];$amount=(int)$x['amount'];$items[]=['id'=>(int)$x['id'],'name'=>$x['name'],'category'=>$x['category'],'amount'=>$amount,'available'=>max(0,$amount-$personal-$assigned),'equippedBySurvivors'=>$personal,'assignedToSquads'=>$assigned,'attackBonus'=>(int)$x['attack_bonus'],'healing'=>(int)$x['healing'],'ammoItem'=>$x['ammo_item']===null?null:(int)$x['ammo_item'],'durability'=>$x['durability']===null?null:(int)$x['durability'],'maxDurability'=>(int)$x['max_durability'],'repairAmount'=>(int)$x['repair_amount'],'defenseBonus'=>(int)$x['defense_bonus']];}
$survivors=[];$s=$db->query("SELECT s.id,s.name,s.hp,s.max_hp,s.attack_stat,s.defense_stat,s.equipped_weapon,s.job_facility,s.fatigue,f.name job_name,i.name weapon,i.attack_bonus,i.ammo_item,i.max_durability,v.durability,COALESCE(a.amount,0) ammo,ht.due treatment_due,ht.soldier_level,ht.hospital_level FROM survivors s LEFT JOIN facilities f ON f.id=s.job_facility LEFT JOIN items i ON i.id=s.equipped_weapon LEFT JOIN inventory v ON v.userid=s.userid AND v.item_id=s.equipped_weapon LEFT JOIN inventory a ON a.userid=s.userid AND a.item_id=i.ammo_item LEFT JOIN hospital_treatments ht ON ht.survivor_id=s.id WHERE s.userid=$uid ORDER BY s.id");while($s&&($x=$s->fetch_assoc())){$treatment=$x['treatment_due']===null?null:['due'=>(int)$x['treatment_due'],'soldierLevel'=>(int)$x['soldier_level'],'hospitalLevel'=>(int)$x['hospital_level']];$available=(int)$x['hp']>0&&(float)$x['fatigue']<90&&$x['job_facility']===null&&!$treatment;$reason=$treatment?'Hospital treatment':((int)$x['hp']<=0?'downed':((float)$x['fatigue']>=90?'exhausted':($x['job_facility']!==null?'working':null)));$survivors[]=['id'=>(int)$x['id'],'name'=>$x['name'],'hp'=>(int)$x['hp'],'maxHp'=>(int)$x['max_hp'],'attack'=>(int)$x['attack_stat'],'defense'=>(int)$x['defense_stat'],'level'=>zv2_soldier_level($x),'weaponId'=>$x['equipped_weapon']===null?null:(int)$x['equipped_weapon'],'weapon'=>$x['weapon'],'weaponBonus'=>(int)($x['attack_bonus']??0),'ammoItem'=>$x['ammo_item']===null?null:(int)$x['ammo_item'],'ammo'=>(int)$x['ammo'],'durability'=>$x['durability']===null?null:(int)$x['durability'],'maxDurability'=>(int)($x['max_durability']??0),'jobFacility'=>$x['job_facility']===null?null:(int)$x['job_facility'],'job'=>$x['job_name'],'fatigue'=>round((float)$x['fatigue']),'treatment'=>$treatment,'available'=>$available,'unavailableReason'=>$reason];}
$hold=$db->query("SELECT buildings FROM strongholds WHERE userid=$uid LIMIT 1")->fetch_assoc();$levels=pipe_nums($hold['buildings']);$shop=(int)($levels[11]??0);$job=null;$jq=$db->query("SELECT j.recipe_id,j.started_at,j.due,r.name,i.name result_name FROM production_jobs j JOIN recipes r ON r.id=j.recipe_id JOIN items i ON i.id=r.result_item WHERE j.userid=$uid LIMIT 1");if($jq&&$jq->num_rows){$j=$jq->fetch_assoc();$job=['recipeId'=>(int)$j['recipe_id'],'name'=>$j['name'],'result'=>$j['result_name'],'startedAt'=>(int)$j['started_at'],'due'=>(int)$j['due']];}
$recipes=[];$rr=$db->query("SELECT r.id,r.name,r.result_item,r.result_amount,r.unlock_tech,r.toolshop_level,r.duration,r.category,i.name result_name,t.name tech_name FROM recipes r JOIN items i ON i.id=r.result_item LEFT JOIN technologies t ON t.id=r.unlock_tech ORDER BY r.category,r.toolshop_level,r.id");while($rr&&($recipe=$rr->fetch_assoc())){$ingredients=[];$materials=true;$ir=$db->query("SELECT ri.item_id,ri.amount,i.name,COALESCE(v.amount,0) owned FROM recipe_ingredients ri JOIN items i ON i.id=ri.item_id LEFT JOIN inventory v ON v.userid=$uid AND v.item_id=ri.item_id WHERE ri.recipe_id=".(int)$recipe['id']);while($ir&&($ing=$ir->fetch_assoc())){$owned=(int)$ing['owned'];$needed=(int)$ing['amount'];if($owned<$needed)$materials=false;$ingredients[]=['id'=>(int)$ing['item_id'],'name'=>$ing['name'],'amount'=>$needed,'owned'=>$owned];}$techOk=$recipe['unlock_tech']===null||zv2_has_tech($uid,(int)$recipe['unlock_tech']);$levelOk=$shop>=(int)$recipe['toolshop_level'];$reason=$shop<=0?'Construct the Toolshop':(!$levelOk?'Toolshop level '.(int)$recipe['toolshop_level'].' required':(!$techOk?'Research '.$recipe['tech_name']:($job?'Production already active':(!$materials?'Missing materials':''))));$recipes[]=['id'=>(int)$recipe['id'],'name'=>$recipe['name'],'category'=>$recipe['category'],'duration'=>(int)$recipe['duration'],'toolshopLevel'=>(int)$recipe['toolshop_level'],'requiredTech'=>$recipe['tech_name'],'techUnlocked'=>$techOk,'result'=>['id'=>(int)$recipe['result_item'],'name'=>$recipe['result_name'],'amount'=>(int)$recipe['result_amount']],'ingredients'=>$ingredients,'canCraft'=>$materials&&$techOk&&$levelOk&&!$job,'reason'=>$reason];}
json_out(['ok'=>true,'items'=>$items,'survivors'=>$survivors,'recipes'=>$recipes,'toolshop'=>['level'=>$shop,'job'=>$job]]);
